"""Pensamiento Computacional EPJA Media N1 y N2, módulo 4 (parte): OAD-13 (evaluar herramientas para trabajar con información), OAD-14 (algoritmos que trabajan con datos), OAD-15 (del algoritmo al lenguaje de programación) y OAD-16 (variedad de algoritmos en Python). Todo en papel, sin computador: el código se lee y se traza a mano; datos inventados."""
from __future__ import annotations

from hc_common import make_build

MATERIALS = ("Papel, lápiz y goma. Todo se resuelve en papel y sin computador ni celular: los algoritmos se escriben en seudocódigo y el código en Python se lee y se traza a mano "
             "con tablas de seguimiento. En los enunciados, « / » marca un salto de línea y « › » una sangría de cuatro espacios. Los datos y cifras son de ejemplo, inventados.")
build = make_build(MATERIALS)

O13 = "EPJA-PECO-NM1y2-OAD-13"
O14 = "EPJA-PECO-NM1y2-OAD-14"
O15 = "EPJA-PECO-NM1y2-OAD-15"
O16 = "EPJA-PECO-NM1y2-OAD-16"
PRIOR = ["Ya uso listas, tablas y números en mi vida diaria, como una boleta, un horario o un registro de gastos.",
         "Sé que un algoritmo es una secuencia de pasos claros para resolver un problema."]


def K(oa, n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_, prior=None):
    build(oa, n, F, use=use, prior=prior or PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes,
          T=T, ctx=ctx, sc=sc, op=op, reinforce=rf, extend=ex_)


